// Regenerate with pier's palette (D154); source revisions: testdata/README.md.
//
//	node --experimental-strip-types coding/interactive/testdata/regenerate.mjs ./pi --write
//
// The golden file is generated by running the real jsdiff (`diff` package)
// and the upstream renderDiff with Node
// (coding/interactive/testdata/diff_golden.txt).

func loadDiffGolden(t *testing.T) map[string]string {
	t.Helper()
	file, err := os.Open("testdata/diff_golden.txt")
	if err != nil {
		t.Fatalf("open golden: %v", err)
	}
	defer file.Close()
	values := map[string]string{}
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		parts := strings.SplitN(line, " => ", 2)
		if len(parts) != 2 {
			t.Fatalf("bad golden line %q", line)
		}
		values[strings.TrimPrefix(parts[0], "d ")] = parts[1]
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("scan: %v", err)
	}
	return values
}

// TestDiffAgainstUpstreamGolden compares DiffWords and RenderDiff with jsdiff.
func TestDiffAgainstUpstreamGolden(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	SetTrueColorSupport(true)
	SetStyleColorsEnabled(true)
	InitTheme("dark", false)

	golden := loadDiffGolden(t)
	data, err := os.ReadFile("testdata/diff_corpus.json")
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	corpus := struct {
		Words   map[string][2]string `json:"words"`
		Renders map[string]string    `json:"renders"`
	}{}
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}

	labels := make([]string, 0, len(corpus.Words))
	for label := range corpus.Words {
		labels = append(labels, label)
	}
	sortStrings(labels)
	for _, label := range labels {
		pair := corpus.Words[label]
		changes := DiffWords(pair[0], pair[1])
		projected := make([]map[string]any, 0, len(changes))
		for _, change := range changes {
			projected = append(projected, map[string]any{
				"value": change.Value, "added": change.Added, "removed": change.Removed,
			})
		}
		checkGolden(t, golden, "words "+label, projected)
	}

	renderLabels := make([]string, 0, len(corpus.Renders))
	for label := range corpus.Renders {
		renderLabels = append(renderLabels, label)
	}
	sortStrings(renderLabels)
	for _, label := range renderLabels {
		got := RenderDiff(corpus.Renders[label], RenderDiffOptions{})
		checkGolden(t, golden, "render "+label, got)
	}
}

// TestDiffHelpers covers the pure helpers.
func TestDiffHelpers(t *testing.T) {
	if prefix := longestCommonPrefix("abcde", "abxyz"); prefix != "ab" {
		t.Fatalf("prefix = %q", prefix)
	}
	if suffix := longestCommonSuffix("abcde", "xycde"); suffix != "cde" {
		t.Fatalf("suffix = %q", suffix)
	}
	if suffix := longestCommonSuffix("", "abc"); suffix != "" {
		t.Fatalf("empty suffix = %q", suffix)
	}
	if got := leadingWs("  x  "); got != "  " {
		t.Fatalf("leadingWs = %q", got)
	}
	if got := trailingWs("  x  "); got != "  " {
		t.Fatalf("trailingWs = %q", got)
	}
	if got := removeSuffix("abcdef", "def"); got != "abc" {
		t.Fatalf("removeSuffix = %q", got)
	}
	if got := removePrefix("abcdef", "abc"); got != "def" {
		t.Fatalf("removePrefix = %q", got)
	}
	if got := maximumOverlap("abab", "abab"); got != "abab" {
		t.Fatalf("maximumOverlap = %q", got)
	}
	if parsed, ok := parseDiffLine("-12 content here"); !ok || parsed.prefix != "-" || parsed.lineNum != "12" || parsed.content != "content here" {
		t.Fatalf("parsed = %+v ok=%v", parsed, ok)
	}
	if _, ok := parseDiffLine("no prefix"); ok {
		t.Fatal("unprefixed line parsed")
	}
	if got := replaceTabs("a\tb"); got != "a   b" {
		t.Fatalf("replaceTabs = %q", got)
	}
}

// jsdiff's tokenizeIncludingWhitespace uses the JS `\s` class, so a run of
// Unicode whitespace stays together and is shared with the next token.
func TestWordTokenizeUnicodeWhitespace(t *testing.T) {
	tokens := diffWordTokenize("a\u00a0\u00a0b")
	want := []string{"a\u00a0\u00a0", "\u00a0\u00a0b"}
	if !reflect.DeepEqual(tokens, want) {
		t.Fatalf("tokens = %q; want %q", tokens, want)
	}
	if joined := diffJoin(tokens); joined != "a\u00a0\u00a0b" {
		t.Fatalf("joined = %q", joined)
	}
}

// jsdiff WordDiff.join strips the JS `\s` class (Unicode whitespace) from
// every token after the first.
func TestDiffJoinStripsUnicodeWhitespace(t *testing.T) {
	if got := diffJoin([]string{"a", "\u3000b"}); got != "ab" {
		t.Fatalf("diffJoin = %q; want %q", got, "ab")
	}
}

// TestRenderDiffKeepsMarkersOnUnicodeLineTerminatorContent pins D481: a diff
// line whose content holds a JS line terminator (U+2028, U+2029 or CR) still
// parses here. diff.ts matches `/^([+-\s])(\s*\d*)\s(.*)$/`, and its `(.*)`
// cannot match a line terminator, so the reference fails the whole match and
// renders the line as a context line.
//
// Reference (pi v1.5.2 b4afdddf components/diff.ts, through the Node harness):
// renderDiff("-1 foo\u2028bar") is one context line,
// "\x1b[38;2;159;159;159m-1 foo\u2028bar\x1b[39m".
func TestRenderDiffKeepsMarkersOnUnicodeLineTerminatorContent(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	SetTrueColorSupport(true)
	SetStyleColorsEnabled(true)
	InitTheme("dark", false)

	for _, separator := range []string{"\u2028", "\u2029", "\r"} {
		text := "-1 foo" + separator + "bar"
		got := RenderDiff(text, RenderDiffOptions{})
		want := ActiveTheme().Fg("toolDiffRemoved", text)
		if got != want {
			t.Errorf("renderDiff(%q) = %q, want the removed line %q", text, got, want)
		}
	}
}

// pi v1.5.0 (f9a26365) components/diff.ts uses jsdiff 8.0.4 diffWords. The
// generated corpus varies whitespace, Unicode, emoji, combining marks and
// punctuation so the tokenizer and whitespace rebalancing stay byte-identical.
func TestDiffWordsRandomCorpus(t *testing.T) {
	data, err := os.ReadFile("testdata/word-diff/fixtures.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixtures []struct {
		Old     string       `json:"old"`
		New     string       `json:"new"`
		Changes []DiffChange `json:"changes"`
	}
	if err := json.Unmarshal(data, &fixtures); err != nil {
		t.Fatal(err)
	}
	if len(fixtures) < 300 {
		t.Fatalf("corpus has %d cases", len(fixtures))
	}
	for index, fixture := range fixtures {
		got := DiffWords(fixture.Old, fixture.New)
		if len(got) != len(fixture.Changes) {
			t.Fatalf("case %d %q -> %q: %d changes, want %d\n got %#v\nwant %#v", index, fixture.Old, fixture.New, len(got), len(fixture.Changes), got, fixture.Changes)
		}
		for i := range got {
			if got[i] != fixture.Changes[i] {
				t.Fatalf("case %d %q -> %q change %d = %#v, want %#v", index, fixture.Old, fixture.New, i, got[i], fixture.Changes[i])
			}
		}
	}
}
